export type ReadingP1Category = 'judgment' | 'trend' | 'other' | 'choice' | 'method' | 'listening';
export type ReadingP1Split = 'development' | 'holdout';

/** 全部为专门编写的合成输入，未读取生产记录。留出集仅在候选冻结后验收。 */
export interface ReadingP1Case extends InterpretationEmpathyCase {
  split: ReadingP1Split;
  category: ReadingP1Category;
  groupId: string;
  pairKind: 'none' | 'same-cards' | 'same-question';
  screen: boolean;
  tags: string[];
}

