type Layout = keyof typeof layouts;
type Options = Partial<
  Pick<
    ReadingP1Case,
    | 'mode'
    | 'previousInterpretation'
    | 'followUpQuestion'
    | 'history'
    | 'date'
    | 'pairKind'
    | 'tags'
  >
> & {
  layout?: Layout;
  group?: string;
  extras?: string[];
};
type Seed = [
  id: string,
  question: string,
  facts: string[],
  goal: string,
  rejectedGoal: string,
  review: string,
  options?: Options,
];

const defaultLayouts: Record<ReadingP1Category, Layout> = {
  judgment: 'single',
  trend: 'three',
  other: 'relationship',
  choice: 'choice',
  method: 'timeline',
  listening: 'singleReverse',
};
const categoryReview: Record<ReadingP1Category, string> = {
  judgment: '前两句回应所问的支持或不支持倾向；不以行动清单替代判断，也不承诺事件必然发生',
  trend: '给出这组牌的主走向和关键阻力，牌位支持理由；不编造已经发生的事件',
  other: '说明牌面支持的互动倾向，一次交代无法确认他人心理；不虚构动机或用免责声明代替回答',
  choice: '按用户明确目标给优先项或唯一决定性缺口，说明何时会翻转；不罗列优缺点后退回随你选择',
  method: '先回应本轮具体目标或纠正，方法服从已知时间和资源；不重复用户已完成或拒绝的步骤',
  listening: '贴合具体经历承接表达，尊重不要建议的目标；不强加任务、追问或保证事情变好',
};

function cardByReference(reference: string): Pick<DrawnCard, 'card' | 'isReversed'> {
  const [id, orientation] = reference.split(':');
  const card = allCards.find((candidate) => candidate.id === id);
  if (!card || (orientation !== undefined && orientation !== 'r'))
    throw new Error(`Invalid P1 fixture card: ${reference}`);
  return { card, isReversed: orientation === 'r' };
}

function buildCases(
  split: ReadingP1Split,
  category: ReadingP1Category,
  seeds: Seed[],
): ReadingP1Case[] {
  return seeds.map(
    ([name, question, knownFacts, goal, rejectedGoal, review, options = {}], index) => {
      const layout = layouts[options.layout ?? defaultLayouts[category]];
      const spread = getSpreadById(layout.spreadId)!;
      if (layout.cards.length !== spread.positions.length)
        throw new Error(`Incomplete P1 fixture spread: ${name}`);
      const id = `p1-${split}-${category}-${name}`;
      return {
        id,
        source: 'synthetic',
        split,
        category,
        mode: options.mode ?? 'initial',
        groupId: options.group ? `p1-${split}-${options.group}` : id,
        pairKind: options.pairKind ?? 'none',
        screen: split === 'development' && index < 2,
        tags: options.tags ?? ['context-provided'],
        question,
        spreadId: spread.id,
        drawnCards: layout.cards.map((reference, cardIndex) => ({
          ...cardByReference(reference),
          position: spread.positions[cardIndex],
        })),
        knownFacts,
        goal,
        rejectedGoals: [rejectedGoal],
        review: [categoryReview[category], review],
        ...(options.mode === 'daily' ? { date: options.date ?? '2026-09-19' } : {}),
        ...(options.previousInterpretation
          ? { previousInterpretation: options.previousInterpretation }
          : {}),
        ...(options.followUpQuestion ? { followUpQuestion: options.followUpQuestion } : {}),
        ...(options.history ? { history: options.history } : {}),
        ...(options.extras
          ? {
              additionalCards: options.extras.map((reference, extraIndex) => ({
                ...cardByReference(reference),
                position: {
                  id: `${id}-extra-${extraIndex + 1}`,
                  name: `Extra ${extraIndex + 1}`,
                  nameCn: `补充指引 ${extraIndex + 1}`,
                  description: '回答本轮追问的补充视角，不改写原牌位',
                },
              })),
            }
          : {}),
      };
    },
  );
}

