export const readingP1DevelopmentCases: ReadingP1Case[] = (
  Object.keys(development) as ReadingP1Category[]
).flatMap((category) => buildCases('development', category, development[category]));
export const readingP1HoldoutCases: ReadingP1Case[] = (
  Object.keys(holdout) as ReadingP1Category[]
).flatMap((category) => buildCases('holdout', category, holdout[category]));
export const readingP1Cases: ReadingP1Case[] = [
  ...readingP1DevelopmentCases,
  ...readingP1HoldoutCases,
];
